// Configuraci├│n del cache y carga secuencial
const BROWSER_CONFIG = {
	// Tama├▒o m├íximo del cach├® (cu├íntos elementos mantener en memoria)
	cacheSize: 500,
	// Configuraci├│n para carga secuencial
	sequential: {
		initialBatchSize: 50, // Cu├íntos elementos cargar inicialmente
		additionalBatchSize: 30, // Cu├íntos elementos cargar en cada lote adicional
		loadThreshold: 0.7, // Porcentaje de scroll para cargar m├ís (0-1)
		scrollLoadDelay: 200, // Tiempo de espera tras detener scroll antes de cargar m├ís
	},
};

// ­ƒôè Logger espec├¡fico para FileBrowser
const logger = clientLogger.withContext('FileBrowser');

// ­ƒÄ» **FileBrowser: Versi├│n Minimalista**
//
// **Objetivos:**
// - Resolver el problema de containerWidth = 0 de forma definitiva
// - Arquitectura simple sin hooks complejos interdependientes
// - Medici├│n directa del contenedor con fallback inmediato
// - Virtualizaci├│n simple y directa
//
// **Cambios principales:**
// - Sin useGridView hook (medici├│n directa en el componente)
// - Sin estados complejos de medici├│n (solo containerWidth)
// - Callback ref con estrategias progresivas de medici├│n
// - Fallback inmediato a 1200px si falla la medici├│n
// - GridItem simplificado sin dependencias pesadas

// ­ƒôØ Definici├│n local del tipo FileItem para soportar miniaturas
// Este tipo se adapta a lo que recibe desde el Server Action getFolderImages
// Todos los campos son serializables para evitar errores de "Only plain objects..."
type FileBrowserFileItem = FileItem & {
	thumbnail?: string | null; // Siempre string o null, nunca Buffer/Uint8Array
	createdAt: string; // ISO string, no Date
	updatedAt: string; // ISO string, no Date
	modifiedAt: string; // ISO string, no Date
	accessedAt: string; // ISO string, no Date
};

interface FileBrowserProps {
	items: FileItem[];
	onItemSelect?: (item: FileItem) => void;
	onItemDoubleClick?: (item: FileItem) => void;
	className?: string;
	/**
	 * Indica si la carpeta est├í cargando o reindexando
	 */
	isLoading?: boolean;
	/**
	 * Indica si la carpeta est├í siendo reindexada
	 */
	isReindexing?: boolean;
	/**
	 * Progreso de reindexado (0-100)
	 */
	reindexProgress?: number;
	/**
	 * Funci├│n para cargar m├ís elementos (scroll infinito)
	 */
	loadMoreItems?: () => void;
}

const _FALLBACK_WIDTH = 1200;
const _ITEM_HEIGHT = 220;
const _ITEM_WIDTH = 200;
const _GAP = 16;

// Interfaz para el men├║ contextual
interface ContextMenuProps {
	open: boolean;
	[key: string]: any;
}

// Componente simple para el men├║ contextual
const ContextMenu = ({ open, ...props }: ContextMenuProps) => {
	if (!open) return null;
	return <div className="context-menu" {...props} />;
};

export const FileBrowser = memo<FileBrowserProps>(function FileBrowser({
	items,
	onItemSelect,
	onItemDoubleClick,
	className,
	isLoading = false,
	isReindexing = false,
	reindexProgress = 0,
	loadMoreItems,
}) {
	// Log para debuggear los items
	console.log('[FileBrowser] Props recibidas:', {
		items: items?.length || 0,
		isLoading,
		isReindexing,
	});

	// ­ƒôè Estados m├¡nimos - Solo lo esencial
	const [_containerWidth, setContainerWidth] = useState<number>(0);
	const [_isViewerOpen, setIsViewerOpen] = useState(false);
	const [_viewerImages, setViewerImages] = useState<ImageItem[]>([]);
	const [_viewerInitialIndex, setViewerInitialIndex] = useState(0);
	const [_loadMoreVisible, setLoadMoreVisible] = useState(false);
	// Estado local para favoritos como soluci├│n temporal
	const [favoriteIds, setFavoriteIds] = useState<Set<string>>(new Set());
	// Ô£à Usar una ref para el seguimiento no causa re-renders
	const lastSelectedItemIndexRef = useRef<number | null>(null);

	// Control de carga progresiva
	const [visibleItemCount, setVisibleItemCount] = useState<number>(BROWSER_CONFIG.sequential.initialBatchSize);
	const _scrollTimerRef = useRef<NodeJS.Timeout | null>(null);
	const loadingMoreRef = useRef<boolean>(false);

	// Estado para el men├║ contextual personalizado
	const [contextMenuFile, setContextMenuFile] = useState<FileItem | null>(null);
	const [contextMenuPosition, setContextMenuPosition] = useState<{ x: number; y: number } | null>(null);

	// ­ƒöì Opciones de vista globales
	const _viewStore = useViewOptionsStore();
	const viewMode = useViewOptionsStore((state) => state.viewMode);
	const itemSize = useViewOptionsStore((state) => state.itemSize);
	const { searchQuery, sortOptions, filterOptions } = useViewOptionsStore();
	const _setSearchQuery = useViewOptionsStore((state) => state.setSearchQuery);

	// Asegurarnos de tener un valor para viewMode
	console.log('[FileBrowser] ViewStore:', {
		viewMode,
		itemSize,
		searchQuery,
		sortOptions,
		filterOptions,
	});

	// Acceso a m├ís opciones de vista para EmptyState
	const viewOptions = useViewOptionsStore();
	const searchInput = viewOptions.searchQuery || '';

	// ­ƒôÉ Refs para medici├│n directa
	const containerRef = useRef<HTMLDivElement>(null);
	const loadMoreRef = useRef<HTMLDivElement>(null);
	const measurementAttemptsRef = useRef(0);

	// ­ƒÅ¬ Stores
	const { selectedIds, activeId, setActiveId, setSelectedIds, toggleSelectedId, clearSelection } = useSelectionStore();
	const { setVisible: setDetailsPanelVisible, setSelectedItems: setDetailsPanelItems } = useDetailsPanel();

	// Funciones para gestionar favoritos localmente
	const _isFavorited = useCallback((id: string) => favoriteIds.has(id), [favoriteIds]);
	const _toggleFavorite = useCallback((id: string) => {
		setFavoriteIds((prev) => {
			const newFavorites = new Set(prev);
			if (newFavorites.has(id)) {
				newFavorites.delete(id);
			} else {
				newFavorites.add(id);
			}
			return newFavorites;
		});
	}, []);

	// ­ƒöì Manejador para el men├║ contextual
	const handleContextMenu = useCallback((_file: FileItem, _e?: React.MouseEvent) => {
		// Deshabilitado temporalmente
		/*
		if (e) {
			e.preventDefault();
			e.stopPropagation();
			setContextMenuPosition({ x: e.clientX, y: e.clientY });
		}
		setContextMenuFile(file);
		*/
	}, []);

	// Seleccionar solo la versi├│n del store para forzar re-renders cuando las miniaturas cambien
	const _imageResourcesVersion = useImageResources((state) => state.version);

	// Cargar m├ís elementos de forma controlada
	const _loadMoreItemsSequentially = useCallback(() => {
		if (loadingMoreRef.current) return;

		// Marcar como cargando
		loadingMoreRef.current = true;
		logger.debug(
			`[FileBrowser] Cargando m├ís elementos secuencialmente: ${visibleItemCount} ÔåÆ ${visibleItemCount + BROWSER_CONFIG.sequential.additionalBatchSize}`
		);

		// Usar setTimeout para dar tiempo a la UI para responder
		setTimeout(() => {
			setVisibleItemCount((prev) => {
				// Limitar al n├║mero m├íximo de elementos o al tama├▒o del cach├®
				const newCount = Math.min(
					prev + BROWSER_CONFIG.sequential.additionalBatchSize,
					items.length,
					BROWSER_CONFIG.cacheSize
				);
				return newCount;
			});

			// Desmarcar como cargando despu├®s de un breve retraso
			setTimeout(() => {
				loadingMoreRef.current = false;
			}, 100);
		}, 50);
	}, [items.length, visibleItemCount]);

	// ­ƒöº **Sistema de medici├│n progresivo**
	// Estrategia: inmediato ÔåÆ RAF ÔåÆ timeout ÔåÆ fallback fijo
	const _measureContainer = useCallback((element: HTMLDivElement) => {
		const attempt = ++measurementAttemptsRef.current;
		logger.debug(`[FileBrowser] Intento medici├│n ${attempt}`);

		const measure = () => {
			const width = element.offsetWidth;
			logger.debug(`[FileBrowser] offsetWidth = ${width}px`);

			if (width > 0) {
				logger.info(`[FileBrowser] Ô£à Medici├│n exitosa: ${width}px`);
				setContainerWidth(width);
				return true;
			}
			return false;
		};

		// Estrategia 1: Medici├│n inmediata
		if (measure()) return;

		// Estrategia 2: requestAnimationFrame
		requestAnimationFrame(() => {
			if (measure()) return;

			// Estrategia 3: setTimeout como ├║ltima oportunidad
			setTimeout(() => {
				if (measure()) return;

				// Estrategia 4: Fallback fijo (no m├ís intentos)
				logger.warn(`[FileBrowser] ! Fall├│ medici├│n despu├®s de ${attempt} intentos, usando fallback: ${1200}px`);
				setContainerWidth(1200);
			}, 100);
		});
	}, []);

	// ­ƒôÄ Callback ref para medici├│n del contenedor
	const _containerCallbackRef = useCallback(
		(element: HTMLDivElement | null) => {
			if (element && containerRef.current !== element) {
				containerRef.current = element;
				// L├│gica de medici├│n (asumimos que ya est├í optimizada)
				const width = element.offsetWidth;
				if (width > 0) {
					setContainerWidth(width);
				} else {
					// Fallback
					setContainerWidth(1200);
				}
			}
		},
		[] // Sin dependencias
	);

	// ­ƒöä Filtrar y ordenar los datos seg├║n las opciones de vista
	// `useFilteredData` ya est├í memoizado internamente, por lo que `filteredItems` es estable
	// si `items` y las opciones de vista no cambian.
	const filteredItems = useFilteredData(items);

	// ­ƒöä Preprocesar los elementos para asegurar que tengan todos los campos necesarios
	const processedItems = useMemo(() => {
		return filteredItems.map((item) => {
			let metadata = null;
			try {
				if (item.metadata && typeof item.metadata === 'string') {
					metadata = JSON.parse(item.metadata);
				}
			} catch (_error) {
				logger.warn(`Error al parsear metadata para el item ${item.id}`);
			}

			// Extraer propiedades de las dimensiones desde metadata si existen
			const width = item.width || metadata?.dimensions?.width || metadata?.width || undefined;
			const height = item.height || metadata?.dimensions?.height || metadata?.height || undefined;

			// Asegurarse de que thumbnail sea una string v├ílida
			const thumbnail =
				typeof item.thumbnail === 'string'
					? item.thumbnail
					: typeof item.src === 'string'
						? item.src
						: `/api/images/${item.id}/thumbnail`;

			// Asegurarse de que src sea una string v├ílida
			const src =
				typeof item.src === 'string'
					? item.src
					: typeof item.thumbnail === 'string'
						? item.thumbnail
						: `/api/images/${item.id}`;

			// Retornar el ├¡tem con las propiedades adicionales
			return {
				...item,
				width,
				height,
				thumbnail,
				src,
			};
		});
	}, [filteredItems]);

	// Limitar los elementos visibles para carga progresiva
	const visibleItems = useMemo(() => {
		const result = processedItems.slice(0, visibleItemCount);
		console.log('[FileBrowser] Datos:', {
			totalItems: items.length,
			processedItems: processedItems.length,
			visibleItemCount,
			visibleItems: result.length,
			viewMode,
			viewType: viewMode || 'grid',
		});
		return result;
	}, [processedItems, visibleItemCount, items.length, viewMode]);

	// Referencia a los elementos actuales para la vista (para selectionActions)
	const currentViewItems = visibleItems;

	// Resetear conteo visible cuando cambian los elementos
	useEffect(() => {
		setVisibleItemCount(Math.min(BROWSER_CONFIG.sequential.initialBatchSize, items.length));
		loadingMoreRef.current = false;
	}, [items]);

	// Definir la funci├│n handleResetView para el EmptyState
	const _handleResetView = useCallback(() => {
		// Limpiar filtros y b├║squeda
		useViewOptionsStore.setState({
			searchQuery: '',
			filterOptions: [],
			viewMode: 'grid', // resetear a la vista por defecto
		});
	}, []);

	// Definir el objeto contextMenu de forma m├ís simple sin depender de handleCloseContextMenu
	const contextMenu = useMemo(
		() => ({
			open: !!contextMenuFile,
			file: contextMenuFile,
			position: contextMenuPosition,
			onClose: () => setContextMenuFile(null),
		}),
		[contextMenuFile, contextMenuPosition]
	);

	// ­ƒöì Manejador de selecci├│n de elementos - ESTABILIZADO con getState()
	// Esta es la clave: la funci├│n no se recrea cuando la selecci├│n cambia.
	const handleItemClick = useCallback(
		(clickedItem: FileItem, e: React.MouseEvent) => {
			const { ctrlKey, metaKey, shiftKey } = e;
			const { selectedIds, setSelectedIds, toggleSelectedId, clearSelection } = useSelectionStore.getState();

			const currentIndex = filteredItems.findIndex((i) => i.id === clickedItem.id);
			if (currentIndex === -1) return;

			// La l├│gica de selecci├│n permanece igual, pero ahora usa el estado m├ís reciente del store
			if (shiftKey && lastSelectedItemIndexRef.current !== null) {
				const start = Math.min(lastSelectedItemIndexRef.current, currentIndex);
				const end = Math.max(lastSelectedItemIndexRef.current, currentIndex);
				const idsToSelect = filteredItems.slice(start, end + 1).map((i) => i.id);
				setSelectedIds(idsToSelect);
			} else if (ctrlKey || metaKey) {
				toggleSelectedId(clickedItem.id);
				lastSelectedItemIndexRef.current = currentIndex;
			} else {
				if (selectedIds.length === 1 && selectedIds[0] === clickedItem.id) {
					clearSelection();
					lastSelectedItemIndexRef.current = null;
				} else {
					setSelectedIds([clickedItem.id]);
					lastSelectedItemIndexRef.current = currentIndex;
				}
			}
			onItemSelect?.(clickedItem);
		},
		[filteredItems, onItemSelect]
	); // Se eliminan las dependencias del store de selecci├│n

	// ­ƒöì Manejador de doble click (abrir visor) - ESTABILIZADO
	const handleItemDoubleClick = useCallback(
		(item: FileItem) => {
			const images = fileItemsToImageItems(processedItems);
			const index = processedItems.findIndex((file) => file.id === item.id);
			if (index !== -1) {
				setViewerImages(images);
				setViewerInitialIndex(index);
				setIsViewerOpen(true);
			}
			onItemDoubleClick?.(item);
		},
		[processedItems, onItemDoubleClick]
	);

	// ­ƒöì Manejador de acciones del men├║ contextual
	const _handleContextMenuAction = useCallback(
		(_action: ContextMenuAction, _item: FileItem, _data?: Record<string, unknown>) => {
			// Deshabilitado temporalmente
			/*
		handleContextAction(action, item, data);
		// Cerrar el men├║ despu├®s de la acci├│n
		setContextMenuFile(null);
		setContextMenuPosition(null);
		*/
		},
		[]
	);

	// ­ƒöä Actualizar el panel de detalles cuando cambie la selecci├│n
	useEffect(() => {
		// Asegurarse de que el panel siempre est├® visible
		const detailsState = useDetailsPanel.getState();

		// Si hay elementos seleccionados
		if (selectedIds.length > 0) {
			const selectedItems = processedItems.filter((item) => selectedIds.includes(item.id));
			if (selectedItems.length > 0) {
				// Convertir a ImageItems para el panel de detalles
				const detailItems = fileItemsToImageItems(selectedItems);

				// Verificar si los elementos seleccionados han cambiado realmente
				const currentItems = detailsState.selectedItems;

				// Comparar IDs para determinar si realmente necesitamos actualizar
				const currentIds = new Set(currentItems.map((item) => item.id));
				const newIds = new Set(detailItems.map((item) => item.id));

				// Solo actualizar si los IDs han cambiado
				const needsUpdate = currentIds.size !== newIds.size || ![...currentIds].every((id) => newIds.has(id));

				if (needsUpdate) {
					// Usar type assertion para compatibilidad temporal
					setDetailsPanelItems(detailItems as any);
				}
			}
		} else {
			// Si no hay elementos seleccionados, mostrar estad├¡sticas de la carpeta
			// Crear un elemento "stats" para mostrar informaci├│n de la carpeta
			const folderStats = {
				id: 'folder-stats',
				name: 'Folder Statistics',
				src: null,
				size: items.reduce((total, item) => total + item.size, 0),
				width: 0,
				height: 0,
				type: 'folder/stats',
				metadata: JSON.stringify({
					totalItems: items.length,
					totalSize: items.reduce((total, item) => total + item.size, 0),
					imageCount: items.filter((item) => item.type?.startsWith('image/')).length,
					videoCount: items.filter((item) => item.type?.startsWith('video/')).length,
					documentCount: items.filter((item) => item.type?.startsWith('text/')).length,
					otherCount: items.filter(
						(item) =>
							!item.type?.startsWith('image/') && !item.type?.startsWith('video/') && !item.type?.startsWith('text/')
					).length,
				}),
			};

			setDetailsPanelItems([folderStats as any]);
		}

		// Asegurarse de que el panel est├® visible
		if (!detailsState.isVisible) {
			setDetailsPanelVisible(true);
		}
	}, [selectedIds, processedItems, items, setDetailsPanelItems, setDetailsPanelVisible]);

	// Efecto para el scroll infinito
	useEffect(() => {
		if (!loadMoreItems || !loadMoreRef.current) return;

		const observer = new IntersectionObserver(
			(entries) => {
				const [entry] = entries;
				if (entry.isIntersecting && !isLoading && !isReindexing) {
					loadMoreItems();
				}
				setLoadMoreVisible(entry.isIntersecting);
			},
			{ threshold: 0.5 }
		);

		observer.observe(loadMoreRef.current);

		return () => {
			observer.disconnect();
		};
	}, [loadMoreItems, isLoading, isReindexing]);

	// Efecto para cerrar el men├║ contextual al hacer clic fuera de ├®l
	useEffect(() => {
		const handleGlobalClick = (e: MouseEvent) => {
			if (contextMenuFile) {
				// Verificar si el clic fue fuera del men├║ contextual
				const contextMenuElement = document.getElementById('file-context-menu');
				if (contextMenuElement && !contextMenuElement.contains(e.target as Node)) {
					// Cerrar el men├║
					setContextMenuFile(null);
					setContextMenuPosition(null);
				}
			}
		};

		// Agregar manejador de eventos global
		document.addEventListener('click', handleGlobalClick);

		// Limpiar al desmontar
		return () => {
			document.removeEventListener('click', handleGlobalClick);
		};
	}, [contextMenuFile]);

	// Eliminado el renderedContent memoizado - ahora se maneja directamente en el JSX principal

	// Referencia al contenedor principal para manejar el foco
	const mainRef = useRef<HTMLDivElement>(null);

	// Manejador de eventos de teclado para navegaci├│n
	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Si el foco no est├í en este componente, no hacer nada
			if (!mainRef.current?.contains(document.activeElement)) return;

			switch (e.key) {
				case 'a':
					// Ctrl+A: Seleccionar todo
					if (e.ctrlKey || e.metaKey) {
						e.preventDefault();
						const allIds = processedItems.map((item) => item.id);
						setSelectedIds(allIds);
					}
					break;

				case 'Escape':
					// Escape: Deseleccionar todo
					e.preventDefault();
					clearSelection();
					break;

				case 'Delete':
					// Delete: Podr├¡a implementar funcionalidad para eliminar elementos seleccionados
					// (Comentado porque requerir├¡a implementaci├│n adicional)
					// if (selectedIds.length > 0) {
					//   e.preventDefault();
					//   // handleDeleteSelected();
					// }
					break;

				// Puedes a├▒adir m├ís atajos de teclado seg├║n necesites
			}
		},
		[processedItems, setSelectedIds, clearSelection]
	);

	// ­ƒöä Usar items directamente con type assertion para compatibilidad
	const _transformedItems = items as FileBrowserFileItem[];

	return (
		<div
			className={cn('h-full w-full bg-background flex flex-col custom-scrollbar', className)}
			onKeyDown={handleKeyDown}
			role="application"
			aria-label="Explorador de archivos"
			ref={mainRef}
			style={{ userSelect: 'none' }}
		>
			<div className="relative flex-1 min-h-0 h-full">
				{/* Vista principal de archivos */}
				<div className="absolute inset-0">
					{isLoading && (
						<div className="h-full w-full flex items-center justify-center">
							<Spinner size="lg" className="text-primary" />
						</div>
					)}

					{!isLoading &&
						(currentViewItems.length === 0 ? (
							<EmptyState
								icon={FileTextIcon}
								title="No se encontraron archivos"
								description={
									searchInput ? `No hay archivos que coincidan con "${searchInput}"` : 'Esta carpeta est├í vac├¡a'
								}
							/>
						) : (
							<AnimatePresence mode="wait">
								<motion.div
									key={viewMode}
									className="h-full w-full"
									initial={{ opacity: 0, y: 10 }}
									animate={{ opacity: 1, y: 0 }}
									exit={{ opacity: 0, y: -10 }}
									transition={{ duration: 0.2 }}
								>
									{viewMode === 'list' && (
										<ListView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'grid' && (
										<SimpleGridView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'masonry' && (
										<MasonryView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'cards' && (
										<CardsView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{(!viewMode ||
										(viewMode !== 'list' && viewMode !== 'grid' && viewMode !== 'masonry' && viewMode !== 'cards')) && (
										<SimpleGridView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}
								</motion.div>
							</AnimatePresence>
						))}
				</div>
			</div>

			{/* Barra de estado */}
			<StatusBar items={currentViewItems} />

			{/* Men├║ contextual */}
			{contextMenu.open && <ContextMenu {...contextMenu} />}
		</div>
	);
});

export default FileBrowser;

/**
 * ­ƒôØ Documentaci├│n r├ípida:
 * - Props nuevas: isLoading, isReindexing, reindexProgress, loadMoreItems
 * - Si isReindexing=true, se muestra overlay de progreso y skeleton
 * - Si isLoading=true, se muestra skeleton de carga
 * - Si containerWidth=0, se muestra skeleton de medici├│n
 * - El overlay es accesible y visible para todos los modos
 * - Integraci├│n con men├║ contextual, panel de detalles y visor de archivos
 * - Soporte para scroll infinito con loadMoreItems
 * - Soporte para favoritos con estado local
 * - Integraci├│n con selecci├│n m├║ltiple de archivos
 *
 * Ejemplo de integraci├│n:
 * <FileBrowser
 *   items={items}
 *   isReindexing={folderStatus.isReindexing}
 *   reindexProgress={folderStatus.progress}
 *   isLoading={isLoading}
 *   loadMoreItems={handleLoadMore}
 * />
 *
 * Caracter├¡sticas principales:
 * 1. Men├║ contextual: Click derecho en cualquier archivo para acceder a acciones
 * 2. Panel de detalles: Se actualiza autom├íticamente al seleccionar archivos
 * 3. Visor de archivos: Doble click en una imagen para abrirla en el visor
 * 4. Favoritos: Toggle de favoritos desde el men├║ contextual
 * 5. Selecci├│n m├║ltiple: Click para seleccionar/deseleccionar archivos
 * 6. Scroll infinito: Carga m├ís elementos al hacer scroll
 */

'use client';

import { FileTextIcon } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { EmptyState } from '@/components/core/data-display';
import { type ImageItem } from '@/components/features/file-viewer/file-viewer';
import { Spinner } from '@/components/ui/spinner';
import { clientLogger } from '@/lib/logger/client-logger';
import { cn } from '@/lib/utils';
import { useDetailsPanel } from '@/store/details-panel.store';
import { useImageResources } from '@/store/image-resources.store';
import { useSelectionStore } from '@/store/ui/selection.slice';
import { useViewOptionsStore } from '@/store/ui/view-options.slice';
import { FileItem } from '@/types/file-item';
import type { ContextMenuAction } from './context-menu/types';
import { useFilteredData } from './hooks/use-filtered-data';
import './styles/scrollbar.css';
import { StatusBar } from './toolbar/status-bar';
import { fileItemsToImageItems } from './utils/file-converters';
import { CardsView } from './views/cards-view';
import { ListView } from './views/list-view';
import { MasonryView } from './views/masonry-view';
import { SimpleGridView } from './views/simple-grid-view';

// Configuraci├│n del cache y carga secuencial
const BROWSER_CONFIG = {
	// Tama├▒o m├íximo del cach├® (cu├íntos elementos mantener en memoria)
	cacheSize: 500,
	// Configuraci├│n para carga secuencial
	sequential: {
		initialBatchSize: 50, // Cu├íntos elementos cargar inicialmente
		additionalBatchSize: 30, // Cu├íntos elementos cargar en cada lote adicional
		loadThreshold: 0.7, // Porcentaje de scroll para cargar m├ís (0-1)
		scrollLoadDelay: 200, // Tiempo de espera tras detener scroll antes de cargar m├ís
	},
};

// ­ƒôè Logger espec├¡fico para FileBrowser
const logger = clientLogger.withContext('FileBrowser');

// ­ƒÄ» **FileBrowser: Versi├│n Minimalista**
//
// **Objetivos:**
// - Resolver el problema de containerWidth = 0 de forma definitiva
// - Arquitectura simple sin hooks complejos interdependientes
// - Medici├│n directa del contenedor con fallback inmediato
// - Virtualizaci├│n simple y directa
//
// **Cambios principales:**
// - Sin useGridView hook (medici├│n directa en el componente)
// - Sin estados complejos de medici├│n (solo containerWidth)
// - Callback ref con estrategias progresivas de medici├│n
// - Fallback inmediato a 1200px si falla la medici├│n
// - GridItem simplificado sin dependencias pesadas

// ­ƒôØ Definici├│n local del tipo FileItem para soportar miniaturas
// Este tipo se adapta a lo que recibe desde el Server Action getFolderImages
// Todos los campos son serializables para evitar errores de "Only plain objects..."
type FileBrowserFileItem = FileItem & {
	thumbnail?: string | null; // Siempre string o null, nunca Buffer/Uint8Array
	createdAt: string; // ISO string, no Date
	updatedAt: string; // ISO string, no Date
	modifiedAt: string; // ISO string, no Date
	accessedAt: string; // ISO string, no Date
};

interface FileBrowserProps {
	items: FileItem[];
	onItemSelect?: (item: FileItem) => void;
	onItemDoubleClick?: (item: FileItem) => void;
	className?: string;
	/**
	 * Indica si la carpeta est├í cargando o reindexando
	 */
	isLoading?: boolean;
	/**
	 * Indica si la carpeta est├í siendo reindexada
	 */
	isReindexing?: boolean;
	/**
	 * Progreso de reindexado (0-100)
	 */
	reindexProgress?: number;
	/**
	 * Funci├│n para cargar m├ís elementos (scroll infinito)
	 */
	loadMoreItems?: () => void;
}

const _FALLBACK_WIDTH = 1200;
const _ITEM_HEIGHT = 220;
const _ITEM_WIDTH = 200;
const _GAP = 16;

// Interfaz para el men├║ contextual
interface ContextMenuProps {
	open: boolean;
	[key: string]: any;
}

// Componente simple para el men├║ contextual
const ContextMenu = ({ open, ...props }: ContextMenuProps) => {
	if (!open) return null;
	return <div className="context-menu" {...props} />;
};

export const FileBrowser = memo<FileBrowserProps>(function FileBrowser({
	items,
	onItemSelect,
	onItemDoubleClick,
	className,
	isLoading = false,
	isReindexing = false,
	reindexProgress = 0,
	loadMoreItems,
}) {
	// Log para debuggear los items
	console.log('[FileBrowser] Props recibidas:', {
		items: items?.length || 0,
		isLoading,
		isReindexing,
	});

	// ­ƒôè Estados m├¡nimos - Solo lo esencial
	const [_containerWidth, setContainerWidth] = useState<number>(0);
	const [_isViewerOpen, setIsViewerOpen] = useState(false);
	const [_viewerImages, setViewerImages] = useState<ImageItem[]>([]);
	const [_viewerInitialIndex, setViewerInitialIndex] = useState(0);
	const [_loadMoreVisible, setLoadMoreVisible] = useState(false);
	// Estado local para favoritos como soluci├│n temporal
	const [favoriteIds, setFavoriteIds] = useState<Set<string>>(new Set());
	// Ô£à Usar una ref para el seguimiento no causa re-renders
	const lastSelectedItemIndexRef = useRef<number | null>(null);

	// Control de carga progresiva
	const [visibleItemCount, setVisibleItemCount] = useState<number>(BROWSER_CONFIG.sequential.initialBatchSize);
	const _scrollTimerRef = useRef<NodeJS.Timeout | null>(null);
	const loadingMoreRef = useRef<boolean>(false);

	// Estado para el men├║ contextual personalizado
	const [contextMenuFile, setContextMenuFile] = useState<FileItem | null>(null);
	const [contextMenuPosition, setContextMenuPosition] = useState<{ x: number; y: number } | null>(null);

	// ­ƒöì Opciones de vista globales
	const _viewStore = useViewOptionsStore();
	const viewMode = useViewOptionsStore((state) => state.viewMode);
	const itemSize = useViewOptionsStore((state) => state.itemSize);
	const { searchQuery, sortOptions, filterOptions } = useViewOptionsStore();
	const _setSearchQuery = useViewOptionsStore((state) => state.setSearchQuery);

	// Asegurarnos de tener un valor para viewMode
	console.log('[FileBrowser] ViewStore:', {
		viewMode,
		itemSize,
		searchQuery,
		sortOptions,
		filterOptions,
	});

	// Acceso a m├ís opciones de vista para EmptyState
	const viewOptions = useViewOptionsStore();
	const searchInput = viewOptions.searchQuery || '';

	// ­ƒôÉ Refs para medici├│n directa
	const containerRef = useRef<HTMLDivElement>(null);
	const loadMoreRef = useRef<HTMLDivElement>(null);
	const measurementAttemptsRef = useRef(0);

	// ­ƒÅ¬ Stores
	const { selectedIds, activeId, setActiveId, setSelectedIds, toggleSelectedId, clearSelection } = useSelectionStore();
	const { setVisible: setDetailsPanelVisible, setSelectedItems: setDetailsPanelItems } = useDetailsPanel();

	// Funciones para gestionar favoritos localmente
	const _isFavorited = useCallback((id: string) => favoriteIds.has(id), [favoriteIds]);
	const _toggleFavorite = useCallback((id: string) => {
		setFavoriteIds((prev) => {
			const newFavorites = new Set(prev);
			if (newFavorites.has(id)) {
				newFavorites.delete(id);
			} else {
				newFavorites.add(id);
			}
			return newFavorites;
		});
	}, []);

	// ­ƒöì Manejador para el men├║ contextual
	const handleContextMenu = useCallback((_file: FileItem, _e?: React.MouseEvent) => {
		// Deshabilitado temporalmente
		/*
		if (e) {
			e.preventDefault();
			e.stopPropagation();
			setContextMenuPosition({ x: e.clientX, y: e.clientY });
		}
		setContextMenuFile(file);
		*/
	}, []);

	// Seleccionar solo la versi├│n del store para forzar re-renders cuando las miniaturas cambien
	const _imageResourcesVersion = useImageResources((state) => state.version);

	// Cargar m├ís elementos de forma controlada
	const _loadMoreItemsSequentially = useCallback(() => {
		if (loadingMoreRef.current) return;

		// Marcar como cargando
		loadingMoreRef.current = true;
		logger.debug(
			`[FileBrowser] Cargando m├ís elementos secuencialmente: ${visibleItemCount} ÔåÆ ${visibleItemCount + BROWSER_CONFIG.sequential.additionalBatchSize}`
		);

		// Usar setTimeout para dar tiempo a la UI para responder
		setTimeout(() => {
			setVisibleItemCount((prev) => {
				// Limitar al n├║mero m├íximo de elementos o al tama├▒o del cach├®
				const newCount = Math.min(
					prev + BROWSER_CONFIG.sequential.additionalBatchSize,
					items.length,
					BROWSER_CONFIG.cacheSize
				);
				return newCount;
			});

			// Desmarcar como cargando despu├®s de un breve retraso
			setTimeout(() => {
				loadingMoreRef.current = false;
			}, 100);
		}, 50);
	}, [items.length, visibleItemCount]);

	// ­ƒöº **Sistema de medici├│n progresivo**
	// Estrategia: inmediato ÔåÆ RAF ÔåÆ timeout ÔåÆ fallback fijo
	const _measureContainer = useCallback((element: HTMLDivElement) => {
		const attempt = ++measurementAttemptsRef.current;
		logger.debug(`[FileBrowser] Intento medici├│n ${attempt}`);

		const measure = () => {
			const width = element.offsetWidth;
			logger.debug(`[FileBrowser] offsetWidth = ${width}px`);

			if (width > 0) {
				logger.info(`[FileBrowser] Ô£à Medici├│n exitosa: ${width}px`);
				setContainerWidth(width);
				return true;
			}
			return false;
		};

		// Estrategia 1: Medici├│n inmediata
		if (measure()) return;

		// Estrategia 2: requestAnimationFrame
		requestAnimationFrame(() => {
			if (measure()) return;

			// Estrategia 3: setTimeout como ├║ltima oportunidad
			setTimeout(() => {
				if (measure()) return;

				// Estrategia 4: Fallback fijo (no m├ís intentos)
				logger.warn(`[FileBrowser] ! Fall├│ medici├│n despu├®s de ${attempt} intentos, usando fallback: ${1200}px`);
				setContainerWidth(1200);
			}, 100);
		});
	}, []);

	// ­ƒôÄ Callback ref para medici├│n del contenedor
	const _containerCallbackRef = useCallback(
		(element: HTMLDivElement | null) => {
			if (element && containerRef.current !== element) {
				containerRef.current = element;
				// L├│gica de medici├│n (asumimos que ya est├í optimizada)
				const width = element.offsetWidth;
				if (width > 0) {
					setContainerWidth(width);
				} else {
					// Fallback
					setContainerWidth(1200);
				}
			}
		},
		[] // Sin dependencias
	);

	// ­ƒöä Filtrar y ordenar los datos seg├║n las opciones de vista
	// `useFilteredData` ya est├í memoizado internamente, por lo que `filteredItems` es estable
	// si `items` y las opciones de vista no cambian.
	const filteredItems = useFilteredData(items);

	// ­ƒöä Preprocesar los elementos para asegurar que tengan todos los campos necesarios
	const processedItems = useMemo(() => {
		return filteredItems.map((item) => {
			let metadata = null;
			try {
				if (item.metadata && typeof item.metadata === 'string') {
					metadata = JSON.parse(item.metadata);
				}
			} catch (_error) {
				logger.warn(`Error al parsear metadata para el item ${item.id}`);
			}

			// Extraer propiedades de las dimensiones desde metadata si existen
			const width = item.width || metadata?.dimensions?.width || metadata?.width || undefined;
			const height = item.height || metadata?.dimensions?.height || metadata?.height || undefined;

			// Asegurarse de que thumbnail sea una string v├ílida
			const thumbnail =
				typeof item.thumbnail === 'string'
					? item.thumbnail
					: typeof item.src === 'string'
						? item.src
						: `/api/images/${item.id}/thumbnail`;

			// Asegurarse de que src sea una string v├ílida
			const src =
				typeof item.src === 'string'
					? item.src
					: typeof item.thumbnail === 'string'
						? item.thumbnail
						: `/api/images/${item.id}`;

			// Retornar el ├¡tem con las propiedades adicionales
			return {
				...item,
				width,
				height,
				thumbnail,
				src,
			};
		});
	}, [filteredItems]);

	// Limitar los elementos visibles para carga progresiva
	const visibleItems = useMemo(() => {
		const result = processedItems.slice(0, visibleItemCount);
		console.log('[FileBrowser] Datos:', {
			totalItems: items.length,
			processedItems: processedItems.length,
			visibleItemCount,
			visibleItems: result.length,
			viewMode,
			viewType: viewMode || 'grid',
		});
		return result;
	}, [processedItems, visibleItemCount, items.length, viewMode]);

	// Referencia a los elementos actuales para la vista (para selectionActions)
	const currentViewItems = visibleItems;

	// Resetear conteo visible cuando cambian los elementos
	useEffect(() => {
		setVisibleItemCount(Math.min(BROWSER_CONFIG.sequential.initialBatchSize, items.length));
		loadingMoreRef.current = false;
	}, [items]);

	// Definir la funci├│n handleResetView para el EmptyState
	const _handleResetView = useCallback(() => {
		// Limpiar filtros y b├║squeda
		useViewOptionsStore.setState({
			searchQuery: '',
			filterOptions: [],
			viewMode: 'grid', // resetear a la vista por defecto
		});
	}, []);

	// Definir el objeto contextMenu de forma m├ís simple sin depender de handleCloseContextMenu
	const contextMenu = useMemo(
		() => ({
			open: !!contextMenuFile,
			file: contextMenuFile,
			position: contextMenuPosition,
			onClose: () => setContextMenuFile(null),
		}),
		[contextMenuFile, contextMenuPosition]
	);

	// ­ƒöì Manejador de selecci├│n de elementos - ESTABILIZADO con getState()
	// Esta es la clave: la funci├│n no se recrea cuando la selecci├│n cambia.
	const handleItemClick = useCallback(
		(clickedItem: FileItem, e: React.MouseEvent) => {
			const { ctrlKey, metaKey, shiftKey } = e;
			const { selectedIds, setSelectedIds, toggleSelectedId, clearSelection } = useSelectionStore.getState();

			const currentIndex = filteredItems.findIndex((i) => i.id === clickedItem.id);
			if (currentIndex === -1) return;

			// La l├│gica de selecci├│n permanece igual, pero ahora usa el estado m├ís reciente del store
			if (shiftKey && lastSelectedItemIndexRef.current !== null) {
				const start = Math.min(lastSelectedItemIndexRef.current, currentIndex);
				const end = Math.max(lastSelectedItemIndexRef.current, currentIndex);
				const idsToSelect = filteredItems.slice(start, end + 1).map((i) => i.id);
				setSelectedIds(idsToSelect);
			} else if (ctrlKey || metaKey) {
				toggleSelectedId(clickedItem.id);
				lastSelectedItemIndexRef.current = currentIndex;
			} else {
				if (selectedIds.length === 1 && selectedIds[0] === clickedItem.id) {
					clearSelection();
					lastSelectedItemIndexRef.current = null;
				} else {
					setSelectedIds([clickedItem.id]);
					lastSelectedItemIndexRef.current = currentIndex;
				}
			}
			onItemSelect?.(clickedItem);
		},
		[filteredItems, onItemSelect]
	); // Se eliminan las dependencias del store de selecci├│n

	// ­ƒöì Manejador de doble click (abrir visor) - ESTABILIZADO
	const handleItemDoubleClick = useCallback(
		(item: FileItem) => {
			const images = fileItemsToImageItems(processedItems);
			const index = processedItems.findIndex((file) => file.id === item.id);
			if (index !== -1) {
				setViewerImages(images);
				setViewerInitialIndex(index);
				setIsViewerOpen(true);
			}
			onItemDoubleClick?.(item);
		},
		[processedItems, onItemDoubleClick]
	);

	// ­ƒöì Manejador de acciones del men├║ contextual
	const _handleContextMenuAction = useCallback(
		(_action: ContextMenuAction, _item: FileItem, _data?: Record<string, unknown>) => {
			// Deshabilitado temporalmente
			/*
		handleContextAction(action, item, data);
		// Cerrar el men├║ despu├®s de la acci├│n
		setContextMenuFile(null);
		setContextMenuPosition(null);
		*/
		},
		[]
	);

	// ­ƒöä Actualizar el panel de detalles cuando cambie la selecci├│n
	useEffect(() => {
		// Asegurarse de que el panel siempre est├® visible
		const detailsState = useDetailsPanel.getState();

		// Si hay elementos seleccionados
		if (selectedIds.length > 0) {
			const selectedItems = processedItems.filter((item) => selectedIds.includes(item.id));
			if (selectedItems.length > 0) {
				// Convertir a ImageItems para el panel de detalles
				const detailItems = fileItemsToImageItems(selectedItems);

				// Verificar si los elementos seleccionados han cambiado realmente
				const currentItems = detailsState.selectedItems;

				// Comparar IDs para determinar si realmente necesitamos actualizar
				const currentIds = new Set(currentItems.map((item) => item.id));
				const newIds = new Set(detailItems.map((item) => item.id));

				// Solo actualizar si los IDs han cambiado
				const needsUpdate = currentIds.size !== newIds.size || ![...currentIds].every((id) => newIds.has(id));

				if (needsUpdate) {
					// Usar type assertion para compatibilidad temporal
					setDetailsPanelItems(detailItems as any);
				}
			}
		} else {
			// Si no hay elementos seleccionados, mostrar estad├¡sticas de la carpeta
			// Crear un elemento "stats" para mostrar informaci├│n de la carpeta
			const folderStats = {
				id: 'folder-stats',
				name: 'Folder Statistics',
				src: null,
				size: items.reduce((total, item) => total + item.size, 0),
				width: 0,
				height: 0,
				type: 'folder/stats',
				metadata: JSON.stringify({
					totalItems: items.length,
					totalSize: items.reduce((total, item) => total + item.size, 0),
					imageCount: items.filter((item) => item.type?.startsWith('image/')).length,
					videoCount: items.filter((item) => item.type?.startsWith('video/')).length,
					documentCount: items.filter((item) => item.type?.startsWith('text/')).length,
					otherCount: items.filter(
						(item) =>
							!item.type?.startsWith('image/') && !item.type?.startsWith('video/') && !item.type?.startsWith('text/')
					).length,
				}),
			};

			setDetailsPanelItems([folderStats as any]);
		}

		// Asegurarse de que el panel est├® visible
		if (!detailsState.isVisible) {
			setDetailsPanelVisible(true);
		}
	}, [selectedIds, processedItems, items, setDetailsPanelItems, setDetailsPanelVisible]);

	// Efecto para el scroll infinito
	useEffect(() => {
		if (!loadMoreItems || !loadMoreRef.current) return;

		const observer = new IntersectionObserver(
			(entries) => {
				const [entry] = entries;
				if (entry.isIntersecting && !isLoading && !isReindexing) {
					loadMoreItems();
				}
				setLoadMoreVisible(entry.isIntersecting);
			},
			{ threshold: 0.5 }
		);

		observer.observe(loadMoreRef.current);

		return () => {
			observer.disconnect();
		};
	}, [loadMoreItems, isLoading, isReindexing]);

	// Efecto para cerrar el men├║ contextual al hacer clic fuera de ├®l
	useEffect(() => {
		const handleGlobalClick = (e: MouseEvent) => {
			if (contextMenuFile) {
				// Verificar si el clic fue fuera del men├║ contextual
				const contextMenuElement = document.getElementById('file-context-menu');
				if (contextMenuElement && !contextMenuElement.contains(e.target as Node)) {
					// Cerrar el men├║
					setContextMenuFile(null);
					setContextMenuPosition(null);
				}
			}
		};

		// Agregar manejador de eventos global
		document.addEventListener('click', handleGlobalClick);

		// Limpiar al desmontar
		return () => {
			document.removeEventListener('click', handleGlobalClick);
		};
	}, [contextMenuFile]);

	// Eliminado el renderedContent memoizado - ahora se maneja directamente en el JSX principal

	// Referencia al contenedor principal para manejar el foco
	const mainRef = useRef<HTMLDivElement>(null);

	// Manejador de eventos de teclado para navegaci├│n
	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Si el foco no est├í en este componente, no hacer nada
			if (!mainRef.current?.contains(document.activeElement)) return;

			switch (e.key) {
				case 'a':
					// Ctrl+A: Seleccionar todo
					if (e.ctrlKey || e.metaKey) {
						e.preventDefault();
						const allIds = processedItems.map((item) => item.id);
						setSelectedIds(allIds);
					}
					break;

				case 'Escape':
					// Escape: Deseleccionar todo
					e.preventDefault();
					clearSelection();
					break;

				case 'Delete':
					// Delete: Podr├¡a implementar funcionalidad para eliminar elementos seleccionados
					// (Comentado porque requerir├¡a implementaci├│n adicional)
					// if (selectedIds.length > 0) {
					//   e.preventDefault();
					//   // handleDeleteSelected();
					// }
					break;

				// Puedes a├▒adir m├ís atajos de teclado seg├║n necesites
			}
		},
		[processedItems, setSelectedIds, clearSelection]
	);

	// ­ƒöä Usar items directamente con type assertion para compatibilidad
	const _transformedItems = items as FileBrowserFileItem[];

	return (
		<div
			className={cn('h-full w-full bg-background flex flex-col custom-scrollbar', className)}
			onKeyDown={handleKeyDown}
			role="application"
			aria-label="Explorador de archivos"
			ref={mainRef}
			style={{ userSelect: 'none' }}
		>
			<div className="relative flex-1 min-h-0 h-full">
				{/* Vista principal de archivos */}
				<div className="absolute inset-0">
					{isLoading && (
						<div className="h-full w-full flex items-center justify-center">
							<Spinner size="lg" className="text-primary" />
						</div>
					)}

					{!isLoading &&
						(currentViewItems.length === 0 ? (
							<EmptyState
								icon={FileTextIcon}
								title="No se encontraron archivos"
								description={
									searchInput ? `No hay archivos que coincidan con "${searchInput}"` : 'Esta carpeta est├í vac├¡a'
								}
							/>
						) : (
							<AnimatePresence mode="wait">
								<motion.div
									key={viewMode}
									className="h-full w-full"
									initial={{ opacity: 0, y: 10 }}
									animate={{ opacity: 1, y: 0 }}
									exit={{ opacity: 0, y: -10 }}
									transition={{ duration: 0.2 }}
								>
									{viewMode === 'list' && (
										<ListView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'grid' && (
										<SimpleGridView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'masonry' && (
										<MasonryView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'cards' && (
										<CardsView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{(!viewMode ||
										(viewMode !== 'list' && viewMode !== 'grid' && viewMode !== 'masonry' && viewMode !== 'cards')) && (
										<SimpleGridView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}
								</motion.div>
							</AnimatePresence>
						))}
				</div>
			</div>

			{/* Barra de estado */}
			<StatusBar items={currentViewItems} />

			{/* Men├║ contextual */}
			{contextMenu.open && <ContextMenu {...contextMenu} />}
		</div>
	);
});

export default FileBrowser;

/**
 * ­ƒôØ Documentaci├│n r├ípida:
 * - Props nuevas: isLoading, isReindexing, reindexProgress, loadMoreItems
 * - Si isReindexing=true, se muestra overlay de progreso y skeleton
 * - Si isLoading=true, se muestra skeleton de carga
 * - Si containerWidth=0, se muestra skeleton de medici├│n
 * - El overlay es accesible y visible para todos los modos
 * - Integraci├│n con men├║ contextual, panel de detalles y visor de archivos
 * - Soporte para scroll infinito con loadMoreItems
 * - Soporte para favoritos con estado local
 * - Integraci├│n con selecci├│n m├║ltiple de archivos
 *
 * Ejemplo de integraci├│n:
 * <FileBrowser
 *   items={items}
 *   isReindexing={folderStatus.isReindexing}
 *   reindexProgress={folderStatus.progress}
 *   isLoading={isLoading}
 *   loadMoreItems={handleLoadMore}
 * />
 *
 * Caracter├¡sticas principales:
 * 1. Men├║ contextual: Click derecho en cualquier archivo para acceder a acciones
 * 2. Panel de detalles: Se actualiza autom├íticamente al seleccionar archivos
 * 3. Visor de archivos: Doble click en una imagen para abrirla en el visor
 * 4. Favoritos: Toggle de favoritos desde el men├║ contextual
 * 5. Selecci├│n m├║ltiple: Click para seleccionar/deseleccionar archivos
 * 6. Scroll infinito: Carga m├ís elementos al hacer scroll
 */

'use client';

import { FileTextIcon } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { EmptyState } from '@/components/core/data-display';
import { type ImageItem } from '@/components/features/file-viewer/file-viewer';
import { Spinner } from '@/components/ui/spinner';
import { clientLogger } from '@/lib/logger/client-logger';
import { cn } from '@/lib/utils';
import { useDetailsPanel } from '@/store/details-panel.store';
import { useImageResources } from '@/store/image-resources.store';
import { useSelectionStore } from '@/store/ui/selection.slice';
import { useViewOptionsStore } from '@/store/ui/view-options.slice';
import { FileItem } from '@/types/file-item';
import type { ContextMenuAction } from './context-menu/types';
import { useFilteredData } from './hooks/use-filtered-data';
import './styles/scrollbar.css';
import { StatusBar } from './toolbar/status-bar';
import { fileItemsToImageItems } from './utils/file-converters';
import { CardsView } from './views/cards-view';
import { ListView } from './views/list-view';
import { MasonryView } from './views/masonry-view';
import { SimpleGridView } from './views/simple-grid-view';

// Configuraci├│n del cache y carga secuencial
const BROWSER_CONFIG = {
	// Tama├▒o m├íximo del cach├® (cu├íntos elementos mantener en memoria)
	cacheSize: 500,
	// Configuraci├│n para carga secuencial
	sequential: {
		initialBatchSize: 50, // Cu├íntos elementos cargar inicialmente
		additionalBatchSize: 30, // Cu├íntos elementos cargar en cada lote adicional
		loadThreshold: 0.7, // Porcentaje de scroll para cargar m├ís (0-1)
		scrollLoadDelay: 200, // Tiempo de espera tras detener scroll antes de cargar m├ís
	},
};

// ­ƒôè Logger espec├¡fico para FileBrowser
const logger = clientLogger.withContext('FileBrowser');

// ­ƒÄ» **FileBrowser: Versi├│n Minimalista**
//
// **Objetivos:**
// - Resolver el problema de containerWidth = 0 de forma definitiva
// - Arquitectura simple sin hooks complejos interdependientes
// - Medici├│n directa del contenedor con fallback inmediato
// - Virtualizaci├│n simple y directa
//
// **Cambios principales:**
// - Sin useGridView hook (medici├│n directa en el componente)
// - Sin estados complejos de medici├│n (solo containerWidth)
// - Callback ref con estrategias progresivas de medici├│n
// - Fallback inmediato a 1200px si falla la medici├│n
// - GridItem simplificado sin dependencias pesadas

// ­ƒôØ Definici├│n local del tipo FileItem para soportar miniaturas
// Este tipo se adapta a lo que recibe desde el Server Action getFolderImages
// Todos los campos son serializables para evitar errores de "Only plain objects..."
type FileBrowserFileItem = FileItem & {
	thumbnail?: string | null; // Siempre string o null, nunca Buffer/Uint8Array
	createdAt: string; // ISO string, no Date
	updatedAt: string; // ISO string, no Date
	modifiedAt: string; // ISO string, no Date
	accessedAt: string; // ISO string, no Date
};

interface FileBrowserProps {
	items: FileItem[];
	onItemSelect?: (item: FileItem) => void;
	onItemDoubleClick?: (item: FileItem) => void;
	className?: string;
	/**
	 * Indica si la carpeta est├í cargando o reindexando
	 */
	isLoading?: boolean;
	/**
	 * Indica si la carpeta est├í siendo reindexada
	 */
	isReindexing?: boolean;
	/**
	 * Progreso de reindexado (0-100)
	 */
	reindexProgress?: number;
	/**
	 * Funci├│n para cargar m├ís elementos (scroll infinito)
	 */
	loadMoreItems?: () => void;
}

const _FALLBACK_WIDTH = 1200;
const _ITEM_HEIGHT = 220;
const _ITEM_WIDTH = 200;
const _GAP = 16;

// Interfaz para el men├║ contextual
interface ContextMenuProps {
	open: boolean;
	[key: string]: any;
}

// Componente simple para el men├║ contextual
const ContextMenu = ({ open, ...props }: ContextMenuProps) => {
	if (!open) return null;
	return <div className="context-menu" {...props} />;
};

export const FileBrowser = memo<FileBrowserProps>(function FileBrowser({
	items,
	onItemSelect,
	onItemDoubleClick,
	className,
	isLoading = false,
	isReindexing = false,
	reindexProgress = 0,
	loadMoreItems,
}) {
	// Log para debuggear los items
	console.log('[FileBrowser] Props recibidas:', {
		items: items?.length || 0,
		isLoading,
		isReindexing,
	});

	// ­ƒôè Estados m├¡nimos - Solo lo esencial
	const [_containerWidth, setContainerWidth] = useState<number>(0);
	const [_isViewerOpen, setIsViewerOpen] = useState(false);
	const [_viewerImages, setViewerImages] = useState<ImageItem[]>([]);
	const [_viewerInitialIndex, setViewerInitialIndex] = useState(0);
	const [_loadMoreVisible, setLoadMoreVisible] = useState(false);
	// Estado local para favoritos como soluci├│n temporal
	const [favoriteIds, setFavoriteIds] = useState<Set<string>>(new Set());
	// Ô£à Usar una ref para el seguimiento no causa re-renders
	const lastSelectedItemIndexRef = useRef<number | null>(null);

	// Control de carga progresiva
	const [visibleItemCount, setVisibleItemCount] = useState<number>(BROWSER_CONFIG.sequential.initialBatchSize);
	const _scrollTimerRef = useRef<NodeJS.Timeout | null>(null);
	const loadingMoreRef = useRef<boolean>(false);

	// Estado para el men├║ contextual personalizado
	const [contextMenuFile, setContextMenuFile] = useState<FileItem | null>(null);
	const [contextMenuPosition, setContextMenuPosition] = useState<{ x: number; y: number } | null>(null);

	// ­ƒöì Opciones de vista globales
	const _viewStore = useViewOptionsStore();
	const viewMode = useViewOptionsStore((state) => state.viewMode);
	const itemSize = useViewOptionsStore((state) => state.itemSize);
	const { searchQuery, sortOptions, filterOptions } = useViewOptionsStore();
	const _setSearchQuery = useViewOptionsStore((state) => state.setSearchQuery);

	// Asegurarnos de tener un valor para viewMode
	console.log('[FileBrowser] ViewStore:', {
		viewMode,
		itemSize,
		searchQuery,
		sortOptions,
		filterOptions,
	});

	// Acceso a m├ís opciones de vista para EmptyState
	const viewOptions = useViewOptionsStore();
	const searchInput = viewOptions.searchQuery || '';

	// ­ƒôÉ Refs para medici├│n directa
	const containerRef = useRef<HTMLDivElement>(null);
	const loadMoreRef = useRef<HTMLDivElement>(null);
	const measurementAttemptsRef = useRef(0);

	// ­ƒÅ¬ Stores
	const { selectedIds, activeId, setActiveId, setSelectedIds, toggleSelectedId, clearSelection } = useSelectionStore();
	const { setVisible: setDetailsPanelVisible, setSelectedItems: setDetailsPanelItems } = useDetailsPanel();

	// Funciones para gestionar favoritos localmente
	const _isFavorited = useCallback((id: string) => favoriteIds.has(id), [favoriteIds]);
	const _toggleFavorite = useCallback((id: string) => {
		setFavoriteIds((prev) => {
			const newFavorites = new Set(prev);
			if (newFavorites.has(id)) {
				newFavorites.delete(id);
			} else {
				newFavorites.add(id);
			}
			return newFavorites;
		});
	}, []);

	// ­ƒöì Manejador para el men├║ contextual
	const handleContextMenu = useCallback((_file: FileItem, _e?: React.MouseEvent) => {
		// Deshabilitado temporalmente
		/*
		if (e) {
			e.preventDefault();
			e.stopPropagation();
			setContextMenuPosition({ x: e.clientX, y: e.clientY });
		}
		setContextMenuFile(file);
		*/
	}, []);

	// Seleccionar solo la versi├│n del store para forzar re-renders cuando las miniaturas cambien
	const _imageResourcesVersion = useImageResources((state) => state.version);

	// Cargar m├ís elementos de forma controlada
	const _loadMoreItemsSequentially = useCallback(() => {
		if (loadingMoreRef.current) return;

		// Marcar como cargando
		loadingMoreRef.current = true;
		logger.debug(
			`[FileBrowser] Cargando m├ís elementos secuencialmente: ${visibleItemCount} ÔåÆ ${visibleItemCount + BROWSER_CONFIG.sequential.additionalBatchSize}`
		);

		// Usar setTimeout para dar tiempo a la UI para responder
		setTimeout(() => {
			setVisibleItemCount((prev) => {
				// Limitar al n├║mero m├íximo de elementos o al tama├▒o del cach├®
				const newCount = Math.min(
					prev + BROWSER_CONFIG.sequential.additionalBatchSize,
					items.length,
					BROWSER_CONFIG.cacheSize
				);
				return newCount;
			});

			// Desmarcar como cargando despu├®s de un breve retraso
			setTimeout(() => {
				loadingMoreRef.current = false;
			}, 100);
		}, 50);
	}, [items.length, visibleItemCount]);

	// ­ƒöº **Sistema de medici├│n progresivo**
	// Estrategia: inmediato ÔåÆ RAF ÔåÆ timeout ÔåÆ fallback fijo
	const _measureContainer = useCallback((element: HTMLDivElement) => {
		const attempt = ++measurementAttemptsRef.current;
		logger.debug(`[FileBrowser] Intento medici├│n ${attempt}`);

		const measure = () => {
			const width = element.offsetWidth;
			logger.debug(`[FileBrowser] offsetWidth = ${width}px`);

			if (width > 0) {
				logger.info(`[FileBrowser] Ô£à Medici├│n exitosa: ${width}px`);
				setContainerWidth(width);
				return true;
			}
			return false;
		};

		// Estrategia 1: Medici├│n inmediata
		if (measure()) return;

		// Estrategia 2: requestAnimationFrame
		requestAnimationFrame(() => {
			if (measure()) return;

			// Estrategia 3: setTimeout como ├║ltima oportunidad
			setTimeout(() => {
				if (measure()) return;

				// Estrategia 4: Fallback fijo (no m├ís intentos)
				logger.warn(`[FileBrowser] ! Fall├│ medici├│n despu├®s de ${attempt} intentos, usando fallback: ${1200}px`);
				setContainerWidth(1200);
			}, 100);
		});
	}, []);

	// ­ƒôÄ Callback ref para medici├│n del contenedor
	const _containerCallbackRef = useCallback(
		(element: HTMLDivElement | null) => {
			if (element && containerRef.current !== element) {
				containerRef.current = element;
				// L├│gica de medici├│n (asumimos que ya est├í optimizada)
				const width = element.offsetWidth;
				if (width > 0) {
					setContainerWidth(width);
				} else {
					// Fallback
					setContainerWidth(1200);
				}
			}
		},
		[] // Sin dependencias
	);

	// ­ƒöä Filtrar y ordenar los datos seg├║n las opciones de vista
	// `useFilteredData` ya est├í memoizado internamente, por lo que `filteredItems` es estable
	// si `items` y las opciones de vista no cambian.
	const filteredItems = useFilteredData(items);

	// ­ƒöä Preprocesar los elementos para asegurar que tengan todos los campos necesarios
	const processedItems = useMemo(() => {
		return filteredItems.map((item) => {
			let metadata = null;
			try {
				if (item.metadata && typeof item.metadata === 'string') {
					metadata = JSON.parse(item.metadata);
				}
			} catch (_error) {
				logger.warn(`Error al parsear metadata para el item ${item.id}`);
			}

			// Extraer propiedades de las dimensiones desde metadata si existen
			const width = item.width || metadata?.dimensions?.width || metadata?.width || undefined;
			const height = item.height || metadata?.dimensions?.height || metadata?.height || undefined;

			// Asegurarse de que thumbnail sea una string v├ílida
			const thumbnail =
				typeof item.thumbnail === 'string'
					? item.thumbnail
					: typeof item.src === 'string'
						? item.src
						: `/api/images/${item.id}/thumbnail`;

			// Asegurarse de que src sea una string v├ílida
			const src =
				typeof item.src === 'string'
					? item.src
					: typeof item.thumbnail === 'string'
						? item.thumbnail
						: `/api/images/${item.id}`;

			// Retornar el ├¡tem con las propiedades adicionales
			return {
				...item,
				width,
				height,
				thumbnail,
				src,
			};
		});
	}, [filteredItems]);

	// Limitar los elementos visibles para carga progresiva
	const visibleItems = useMemo(() => {
		const result = processedItems.slice(0, visibleItemCount);
		console.log('[FileBrowser] Datos:', {
			totalItems: items.length,
			processedItems: processedItems.length,
			visibleItemCount,
			visibleItems: result.length,
			viewMode,
			viewType: viewMode || 'grid',
		});
		return result;
	}, [processedItems, visibleItemCount, items.length, viewMode]);

	// Referencia a los elementos actuales para la vista (para selectionActions)
	const currentViewItems = visibleItems;

	// Resetear conteo visible cuando cambian los elementos
	useEffect(() => {
		setVisibleItemCount(Math.min(BROWSER_CONFIG.sequential.initialBatchSize, items.length));
		loadingMoreRef.current = false;
	}, [items]);

	// Definir la funci├│n handleResetView para el EmptyState
	const _handleResetView = useCallback(() => {
		// Limpiar filtros y b├║squeda
		useViewOptionsStore.setState({
			searchQuery: '',
			filterOptions: [],
			viewMode: 'grid', // resetear a la vista por defecto
		});
	}, []);

	// Definir el objeto contextMenu de forma m├ís simple sin depender de handleCloseContextMenu
	const contextMenu = useMemo(
		() => ({
			open: !!contextMenuFile,
			file: contextMenuFile,
			position: contextMenuPosition,
			onClose: () => setContextMenuFile(null),
		}),
		[contextMenuFile, contextMenuPosition]
	);

	// ­ƒöì Manejador de selecci├│n de elementos - ESTABILIZADO con getState()
	// Esta es la clave: la funci├│n no se recrea cuando la selecci├│n cambia.
	const handleItemClick = useCallback(
		(clickedItem: FileItem, e: React.MouseEvent) => {
			const { ctrlKey, metaKey, shiftKey } = e;
			const { selectedIds, setSelectedIds, toggleSelectedId, clearSelection } = useSelectionStore.getState();

			const currentIndex = filteredItems.findIndex((i) => i.id === clickedItem.id);
			if (currentIndex === -1) return;

			// La l├│gica de selecci├│n permanece igual, pero ahora usa el estado m├ís reciente del store
			if (shiftKey && lastSelectedItemIndexRef.current !== null) {
				const start = Math.min(lastSelectedItemIndexRef.current, currentIndex);
				const end = Math.max(lastSelectedItemIndexRef.current, currentIndex);
				const idsToSelect = filteredItems.slice(start, end + 1).map((i) => i.id);
				setSelectedIds(idsToSelect);
			} else if (ctrlKey || metaKey) {
				toggleSelectedId(clickedItem.id);
				lastSelectedItemIndexRef.current = currentIndex;
			} else {
				if (selectedIds.length === 1 && selectedIds[0] === clickedItem.id) {
					clearSelection();
					lastSelectedItemIndexRef.current = null;
				} else {
					setSelectedIds([clickedItem.id]);
					lastSelectedItemIndexRef.current = currentIndex;
				}
			}
			onItemSelect?.(clickedItem);
		},
		[filteredItems, onItemSelect]
	); // Se eliminan las dependencias del store de selecci├│n

	// ­ƒöì Manejador de doble click (abrir visor) - ESTABILIZADO
	const handleItemDoubleClick = useCallback(
		(item: FileItem) => {
			const images = fileItemsToImageItems(processedItems);
			const index = processedItems.findIndex((file) => file.id === item.id);
			if (index !== -1) {
				setViewerImages(images);
				setViewerInitialIndex(index);
				setIsViewerOpen(true);
			}
			onItemDoubleClick?.(item);
		},
		[processedItems, onItemDoubleClick]
	);

	// ­ƒöì Manejador de acciones del men├║ contextual
	const _handleContextMenuAction = useCallback(
		(_action: ContextMenuAction, _item: FileItem, _data?: Record<string, unknown>) => {
			// Deshabilitado temporalmente
			/*
		handleContextAction(action, item, data);
		// Cerrar el men├║ despu├®s de la acci├│n
		setContextMenuFile(null);
		setContextMenuPosition(null);
		*/
		},
		[]
	);

	// ­ƒöä Actualizar el panel de detalles cuando cambie la selecci├│n
	useEffect(() => {
		// Asegurarse de que el panel siempre est├® visible
		const detailsState = useDetailsPanel.getState();

		// Si hay elementos seleccionados
		if (selectedIds.length > 0) {
			const selectedItems = processedItems.filter((item) => selectedIds.includes(item.id));
			if (selectedItems.length > 0) {
				// Convertir a ImageItems para el panel de detalles
				const detailItems = fileItemsToImageItems(selectedItems);

				// Verificar si los elementos seleccionados han cambiado realmente
				const currentItems = detailsState.selectedItems;

				// Comparar IDs para determinar si realmente necesitamos actualizar
				const currentIds = new Set(currentItems.map((item) => item.id));
				const newIds = new Set(detailItems.map((item) => item.id));

				// Solo actualizar si los IDs han cambiado
				const needsUpdate = currentIds.size !== newIds.size || ![...currentIds].every((id) => newIds.has(id));

				if (needsUpdate) {
					// Usar type assertion para compatibilidad temporal
					setDetailsPanelItems(detailItems as any);
				}
			}
		} else {
			// Si no hay elementos seleccionados, mostrar estad├¡sticas de la carpeta
			// Crear un elemento "stats" para mostrar informaci├│n de la carpeta
			const folderStats = {
				id: 'folder-stats',
				name: 'Folder Statistics',
				src: null,
				size: items.reduce((total, item) => total + item.size, 0),
				width: 0,
				height: 0,
				type: 'folder/stats',
				metadata: JSON.stringify({
					totalItems: items.length,
					totalSize: items.reduce((total, item) => total + item.size, 0),
					imageCount: items.filter((item) => item.type?.startsWith('image/')).length,
					videoCount: items.filter((item) => item.type?.startsWith('video/')).length,
					documentCount: items.filter((item) => item.type?.startsWith('text/')).length,
					otherCount: items.filter(
						(item) =>
							!item.type?.startsWith('image/') && !item.type?.startsWith('video/') && !item.type?.startsWith('text/')
					).length,
				}),
			};

			setDetailsPanelItems([folderStats as any]);
		}

		// Asegurarse de que el panel est├® visible
		if (!detailsState.isVisible) {
			setDetailsPanelVisible(true);
		}
	}, [selectedIds, processedItems, items, setDetailsPanelItems, setDetailsPanelVisible]);

	// Efecto para el scroll infinito
	useEffect(() => {
		if (!loadMoreItems || !loadMoreRef.current) return;

		const observer = new IntersectionObserver(
			(entries) => {
				const [entry] = entries;
				if (entry.isIntersecting && !isLoading && !isReindexing) {
					loadMoreItems();
				}
				setLoadMoreVisible(entry.isIntersecting);
			},
			{ threshold: 0.5 }
		);

		observer.observe(loadMoreRef.current);

		return () => {
			observer.disconnect();
		};
	}, [loadMoreItems, isLoading, isReindexing]);

	// Efecto para cerrar el men├║ contextual al hacer clic fuera de ├®l
	useEffect(() => {
		const handleGlobalClick = (e: MouseEvent) => {
			if (contextMenuFile) {
				// Verificar si el clic fue fuera del men├║ contextual
				const contextMenuElement = document.getElementById('file-context-menu');
				if (contextMenuElement && !contextMenuElement.contains(e.target as Node)) {
					// Cerrar el men├║
					setContextMenuFile(null);
					setContextMenuPosition(null);
				}
			}
		};

		// Agregar manejador de eventos global
		document.addEventListener('click', handleGlobalClick);

		// Limpiar al desmontar
		return () => {
			document.removeEventListener('click', handleGlobalClick);
		};
	}, [contextMenuFile]);

	// Eliminado el renderedContent memoizado - ahora se maneja directamente en el JSX principal

	// Referencia al contenedor principal para manejar el foco
	const mainRef = useRef<HTMLDivElement>(null);

	// Manejador de eventos de teclado para navegaci├│n
	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			// Si el foco no est├í en este componente, no hacer nada
			if (!mainRef.current?.contains(document.activeElement)) return;

			switch (e.key) {
				case 'a':
					// Ctrl+A: Seleccionar todo
					if (e.ctrlKey || e.metaKey) {
						e.preventDefault();
						const allIds = processedItems.map((item) => item.id);
						setSelectedIds(allIds);
					}
					break;

				case 'Escape':
					// Escape: Deseleccionar todo
					e.preventDefault();
					clearSelection();
					break;

				case 'Delete':
					// Delete: Podr├¡a implementar funcionalidad para eliminar elementos seleccionados
					// (Comentado porque requerir├¡a implementaci├│n adicional)
					// if (selectedIds.length > 0) {
					//   e.preventDefault();
					//   // handleDeleteSelected();
					// }
					break;

				// Puedes a├▒adir m├ís atajos de teclado seg├║n necesites
			}
		},
		[processedItems, setSelectedIds, clearSelection]
	);

	// ­ƒöä Usar items directamente con type assertion para compatibilidad
	const _transformedItems = items as FileBrowserFileItem[];

	return (
		<div
			className={cn('h-full w-full bg-background flex flex-col custom-scrollbar', className)}
			onKeyDown={handleKeyDown}
			role="application"
			aria-label="Explorador de archivos"
			ref={mainRef}
			style={{ userSelect: 'none' }}
		>
			<div className="relative flex-1 min-h-0 h-full">
				{/* Vista principal de archivos */}
				<div className="absolute inset-0">
					{isLoading && (
						<div className="h-full w-full flex items-center justify-center">
							<Spinner size="lg" className="text-primary" />
						</div>
					)}

					{!isLoading &&
						(currentViewItems.length === 0 ? (
							<EmptyState
								icon={FileTextIcon}
								title="No se encontraron archivos"
								description={
									searchInput ? `No hay archivos que coincidan con "${searchInput}"` : 'Esta carpeta est├í vac├¡a'
								}
							/>
						) : (
							<AnimatePresence mode="wait">
								<motion.div
									key={viewMode}
									className="h-full w-full"
									initial={{ opacity: 0, y: 10 }}
									animate={{ opacity: 1, y: 0 }}
									exit={{ opacity: 0, y: -10 }}
									transition={{ duration: 0.2 }}
								>
									{viewMode === 'list' && (
										<ListView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'grid' && (
										<SimpleGridView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'masonry' && (
										<MasonryView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{viewMode === 'cards' && (
										<CardsView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}

									{(!viewMode ||
										(viewMode !== 'list' && viewMode !== 'grid' && viewMode !== 'masonry' && viewMode !== 'cards')) && (
										<SimpleGridView
											items={currentViewItems}
											onItemClick={handleItemClick}
											onItemDoubleClick={handleItemDoubleClick}
											onContextMenu={handleContextMenu}
										/>
									)}
								</motion.div>
							</AnimatePresence>
						))}
				</div>
			</div>

			{/* Barra de estado */}
			<StatusBar items={currentViewItems} />

			{/* Men├║ contextual */}
			{contextMenu.open && <ContextMenu {...contextMenu} />}
		</div>
	);
});

export default FileBrowser;

/**
 * ­ƒôØ Documentaci├│n r├ípida:
 * - Props nuevas: isLoading, isReindexing, reindexProgress, loadMoreItems
 * - Si isReindexing=true, se muestra overlay de progreso y skeleton
 * - Si isLoading=true, se muestra skeleton de carga
 * - Si containerWidth=0, se muestra skeleton de medici├│n
 * - El overlay es accesible y visible para todos los modos
 * - Integraci├│n con men├║ contextual, panel de detalles y visor de archivos
 * - Soporte para scroll infinito con loadMoreItems
 * - Soporte para favoritos con estado local
 * - Integraci├│n con selecci├│n m├║ltiple de archivos
 *
 * Ejemplo de integraci├│n:
 * <FileBrowser
 *   items={items}
 *   isReindexing={folderStatus.isReindexing}
 *   reindexProgress={folderStatus.progress}
 *   isLoading={isLoading}
 *   loadMoreItems={handleLoadMore}
 * />
 *
 * Caracter├¡sticas principales:
 * 1. Men├║ contextual: Click derecho en cualquier archivo para acceder a acciones
 * 2. Panel de detalles: Se actualiza autom├íticamente al seleccionar archivos
 * 3. Visor de archivos: Doble click en una imagen para abrirla en el visor
 * 4. Favoritos: Toggle de favoritos desde el men├║ contextual
 * 5. Selecci├│n m├║ltiple: Click para seleccionar/deseleccionar archivos
 * 6. Scroll infinito: Carga m├ís elementos al hacer scroll
 */
